<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, errorMessage } from '../services/api'
import { useAuthStore } from '../stores/auth'
import { useFeedbackStore } from '../stores/feedback'
const router = useRouter(); const auth = useAuthStore(); const feedback = useFeedbackStore(); const data = ref({ users: [], counts: {}, allClientsActive: false }); const loading = ref(false); const dialog = ref(false); const showPassword = ref(false)
const sortKey = ref('user'); const sortDesc = ref(false)
const catalogs = computed(() => data.value.catalogs || [])
const filters = reactive({ q: '', role: null, status: null }); const form = reactive({ username: '', password: '', full_name: '', email: '', additional_emails: [], nif: '', company_name: '', phone: '', carrier: '', role: 'client', active: true, catalogs: ['villas'] }); let timer
const filtered = computed(() => { const rows = data.value.users.filter(u => (!filters.q || `${u.username} ${u.fullName} ${u.companyName} ${u.email} ${u.nif}`.toLowerCase().includes(filters.q.toLowerCase())) && (!filters.role || u.role === filters.role) && (filters.status === null || u.active === filters.status)); const field = { user: u => `${u.fullName} ${u.username} ${u.companyName || ''}`, contact: u => `${u.email || ''} ${u.phone || ''}`, login: u => u.lastLoginAt ? new Date(u.lastLoginAt).getTime() : 0, role: u => u.role, active: u => Number(Boolean(u.active)) }[sortKey.value] || (u => u.fullName); return rows.sort((a,b) => { const left = field(a), right = field(b); const result = typeof left === 'number' ? left - right : String(left).localeCompare(String(right), 'pt'); return sortDesc.value ? -result : result }) })
const dateTime = value => value ? new Intl.DateTimeFormat('pt-PT', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : 'Nunca entrou'
function sortBy(key) { if (sortKey.value === key) sortDesc.value = !sortDesc.value; else { sortKey.value = key; sortDesc.value = false } }
async function load() { loading.value = true; try { data.value = (await api.get('/admin/users')).data } catch(e) { feedback.show(errorMessage(e), 'error') } finally { loading.value = false } }
async function toggle(user) { const old = user.active; user.active = !old; try { await api.patch(`/admin/users/${user.id}/active`, { active: user.active }); feedback.show(`${user.fullName} ${user.active ? 'ativado' : 'desativado'}.`) } catch(e) { user.active = old; feedback.show(errorMessage(e), 'error') } }
async function toggleCatalog(user, slug) { const previous = [...(user.catalogs || [])]; const next = previous.includes(slug) ? previous.filter(item => item !== slug) : [...previous, slug]; user.catalogs = next; try { const { data: result } = await api.patch(`/admin/users/${user.id}/catalogs`, { catalogs: next }); user.catalogs = result.user.catalogs; if (Number(auth.user?.id) === Number(user.id)) auth.user = { ...auth.user, catalogs: [...result.user.catalogs] }; feedback.show('Acesso aos catálogos atualizado.') } catch(e) { user.catalogs = previous; feedback.show(errorMessage(e), 'error') } }
async function toggleAll(value) { if (!await feedback.confirm(`${value ? 'Ativar' : 'Desativar'} todos os clientes normais?`)) return load(); try { await api.patch('/admin/clients/active', { active: value }); await load(); feedback.show('Clientes atualizados.') } catch(e) { feedback.show(errorMessage(e), 'error') } }
async function create() { try { const { data: created } = await api.post('/admin/users', form); dialog.value = false; await load(); feedback.show(created.emailStatus === 'sent' ? 'Utilizador criado e email enviado.' : 'Utilizador criado, mas o email não foi enviado.', created.emailStatus === 'sent' ? 'success' : 'warning'); Object.assign(form, { username:'', password:'', full_name:'', email:'', additional_emails:[], nif:'', company_name:'', phone:'', carrier:'', role:'client', active:true, catalogs:['villas'] }) } catch(e) { feedback.show(errorMessage(e), 'error') } }
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>Utilizadores</h1><p>Clientes e administradores, organizados num único lugar.</p></div><v-btn color="primary" prepend-icon="mdi-account-plus" @click="dialog = true">Novo utilizador</v-btn></div>
  <v-row class="mb-2"><v-col v-for="item in [['Todos',data.counts.all],['Clientes',data.counts.client],['Administradores',data.counts.admin],['Inativos',data.counts.inactive]]" :key="item[0]" cols="6" md="3"><v-card class="soft-card metric"><div class="metric-label">{{ item[0] }}</div><div class="metric-value">{{ item[1] || 0 }}</div></v-card></v-col></v-row>
  <v-card class="soft-card pa-4 mb-5"><v-row density="compact" class="align-center"><v-col cols="12" md="5"><v-text-field v-model="filters.q" hide-details clearable label="Pesquisar em tempo real" prepend-inner-icon="mdi-magnify" /></v-col><v-col cols="6" md="2"><v-select v-model="filters.role" hide-details clearable label="Tipo" :items="[{title:'Cliente',value:'client'},{title:'Administrador',value:'admin'},{title:'Developer legado',value:'developer'}]" /></v-col><v-col cols="6" md="2"><v-select v-model="filters.status" hide-details clearable label="Estado" :items="[{title:'Ativo',value:true},{title:'Inativo',value:false}]" /></v-col><v-col cols="12" md="3"><v-switch :model-value="data.allClientsActive" hide-details color="success" label="Todos os clientes ativos" @update:model-value="toggleAll" /></v-col></v-row></v-card>
  <v-card class="soft-card table-wrap">
    <v-progress-linear v-if="loading" indeterminate />
    <v-table>
      <thead><tr><th class="cursor-pointer" @click="sortBy('user')">Utilizador <v-icon size="14">{{sortKey==='user'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="cursor-pointer" @click="sortBy('contact')">Contacto <v-icon size="14">{{sortKey==='contact'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="cursor-pointer" @click="sortBy('login')">Último login <v-icon size="14">{{sortKey==='login'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="text-center">Catálogos</th><th class="text-center cursor-pointer" @click="sortBy('role')">Tipo <v-icon size="14">{{sortKey==='role'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="text-center cursor-pointer" @click="sortBy('active')">Ativo <v-icon size="14">{{sortKey==='active'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th></th></tr></thead>
      <tbody><tr v-for="user in filtered" :key="user.id" class="clickable"><td @click="router.push(`/admin/utilizadores/${user.id}`)"><b>{{ user.fullName }}</b><div class="text-caption text-medium-emphasis">@{{ user.username }} · {{ user.companyName || 'Sem empresa' }}</div></td><td @click="router.push(`/admin/utilizadores/${user.id}`)">{{ user.email || 'Sem email' }}<div class="text-caption">{{ user.phone || 'Sem telefone' }}</div></td><td @click="router.push(`/admin/utilizadores/${user.id}`)"><v-chip size="small" variant="tonal" :color="user.lastLoginAt ? 'success' : 'grey'">{{ dateTime(user.lastLoginAt) }}</v-chip></td><td class="text-center"><div class="d-flex justify-center ga-1"><v-tooltip v-for="catalog in catalogs" :key="catalog.slug" :text="`${user.catalogs?.includes(catalog.slug) ? 'Remover' : 'Dar'} acesso a ${catalog.label}`"><template #activator="{ props }"><v-chip v-bind="props" size="small" :prepend-icon="catalog.icon" :color="user.catalogs?.includes(catalog.slug) ? 'success' : 'grey'" :variant="user.catalogs?.includes(catalog.slug) ? 'flat' : 'outlined'" @click.stop="toggleCatalog(user, catalog.slug)">{{ catalog.label }}</v-chip></template></v-tooltip></div></td><td class="text-center"><v-chip size="small" variant="tonal">{{ user.role === 'client' ? 'Cliente' : user.role === 'admin' ? 'Admin' : 'Developer legado' }}</v-chip></td><td class="text-center"><v-switch :model-value="user.active" hide-details color="success" class="d-inline-flex" @update:model-value="toggle(user)" /></td><td><v-btn icon="mdi-chevron-right" variant="text" @click="router.push(`/admin/utilizadores/${user.id}`)" /></td></tr></tbody>
    </v-table>
    <div v-if="!loading && !filtered.length" class="empty-state">Nenhum utilizador corresponde à pesquisa.</div>
  </v-card>
  <v-dialog v-model="dialog"><v-card><v-card-title class="pa-6 pb-2">Criar utilizador</v-card-title><v-card-text class="pa-6"><v-row density="compact"><v-col cols="12" md="6"><v-text-field v-model="form.full_name" label="Nome completo" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.company_name" label="Empresa" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.username" label="Utilizador" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.password" label="Password" :type="showPassword?'text':'password'" :append-inner-icon="showPassword?'mdi-eye-off':'mdi-eye'" @click:append-inner="showPassword=!showPassword" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.email" type="email" label="Email principal" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" label="Telefone" /></v-col><v-col cols="12"><v-combobox v-model="form.additional_emails" multiple chips closable-chips label="Emails adicionais para encomendas" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.nif" label="NIF" /></v-col><v-col cols="12" md="6"><v-select v-model="form.role" label="Tipo" :items="[{title:'Cliente',value:'client'},{title:'Administrador',value:'admin'}]" /></v-col><v-col cols="12"><v-select v-model="form.catalogs" :items="catalogs" item-title="label" item-value="slug" multiple chips closable-chips label="Catálogos visíveis" prepend-inner-icon="mdi-bookshelf" /></v-col><v-col cols="12"><v-text-field v-model="form.carrier" label="Transportadora / Transitário" prepend-inner-icon="mdi-truck-outline" /></v-col><v-col cols="12"><v-switch v-model="form.active" color="success" label="Utilizador ativo" /></v-col></v-row></v-card-text><v-card-actions class="px-6 pb-6"><v-spacer/><v-btn variant="text" @click="dialog=false">Cancelar</v-btn><v-btn color="primary" @click="create">Criar utilizador</v-btn></v-card-actions></v-card></v-dialog>
</div></template>
